function validate([num]) {
  if (typeof num !== 'string' || !/^[1-9][0-9]*$/.test(num)) return 'num is a decimal number of at least 1, written without leading zeros.';
  if (num.length > 13 || Number(num) > 1000000000000) return 'num is at most 10^12.';
  return null;
}

