function toHexspeak(num) {
  const hex = Number(num).toString(16).toUpperCase();
  let result = '';

  for (const digit of hex) {
    if (digit === '0') {
      result += 'O';
    } else if (digit === '1') {
      result += 'I';
    } else if (digit >= 'A' && digit <= 'F') {
      result += digit;
    } else {
      return 'ERROR';
    }
  }
  return result;
}

brute:
function toHexspeak(num) {
  const symbols = 'OI23456789ABCDEF';
  let value = BigInt(num);
  let text = '';
  while (value > 0n) {
    text = symbols[Number(value % 16n)] + text;
    value /= 16n;
  }
  return /^[ABCDEFIO]+$/.test(text) ? text : 'ERROR';
}

