function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const maxDigits = size === 'large' ? 10 : 4;
  const symbols = '01ABCDEF';
  for (;;) {
    let value;
    const roll = rand();
    if (roll < 0.65) {
      // Build a number whose base-16 form uses only Hexspeak-friendly digits.
      const length = int(1, maxDigits);
      const chars = [symbols[int(1, 7)]];
      for (let i = 1; i < length; i++) chars.push(symbols[int(0, 7)]);
      // Sometimes spoil one digit so the answer turns into ERROR.
      if (rand() < 0.3) chars[int(0, length - 1)] = String(int(2, 9));
      value = parseInt(chars.join(''), 16);
    } else if (size === 'large') {
      value = int(1, 1000000000000);
    } else {
      value = int(1, 300);
    }
    if (value >= 1 && value <= 1000000000000) return [String(value)];
  }
}
